#!/bin/bash
# Usage: mcp_call.sh <tools/call params JSON>
# Speaks raw MCP JSON-RPC over stdio to the same command Hermes registered.
PARAMS="$1"
{
  echo '{"jsonrpc":"2.0","id":1,"method":"initialize","params":{"protocolVersion":"2025-06-18","capabilities":{},"clientInfo":{"name":"hermes-install-check","version":"1"}}}'
  echo '{"jsonrpc":"2.0","method":"notifications/initialized"}'
  echo "{\"jsonrpc\":\"2.0\",\"id\":2,\"method\":\"tools/call\",\"params\":$PARAMS}"
  sleep 12
} | GBRAIN_HOME=/harness-state /harness-state/.bun/bin/gbrain serve --surface starter --advertise verbs 2>/dev/null | grep '"id":2'
